INSERT INTO business_info (id,business_name,description,address,district,city,contact_phone,appointment_instructions) VALUES
('f8c577a4-353d-486e-91d0-7504ddb836b0','Consultorio Demo Ica','Consultorio ficticio usado exclusivamente para una demostración académica.','Av. Los Ejemplos 123','Ica','Ica',NULL,'Para solicitar una cita, escribe al canal de contacto que configure el equipo; esta conversación no confirma reservas.');
INSERT INTO faq (id,category,question,answer,keywords,active,sort_order) VALUES
('00000000-0000-4000-8000-000000000001','HORARIOS','¿Cuál es el horario de lunes a viernes?','Dato ficticio de ejemplo: atendemos de lunes a viernes de 09:00 a 18:00.','horario horarios atienden atencion lunes martes miercoles jueves viernes semana',true,1),
('00000000-0000-4000-8000-000000000002','HORARIOS','¿Atienden los sábados?','Dato ficticio de ejemplo: los sábados atendemos de 09:00 a 13:00.','sabado sabados fin semana atienden abierto horario',true,2),
('00000000-0000-4000-8000-000000000003','HORARIOS','¿Abren los domingos?','Dato ficticio de ejemplo: los domingos el consultorio permanece cerrado.','domingo domingos cerrado abren atienden horario',true,3),
('00000000-0000-4000-8000-000000000004','UBICACION','¿Dónde se ubican?','Dato ficticio de ejemplo: estamos en Av. Los Ejemplos 123, distrito y ciudad de Ica.','ubicacion ubican ubicados direccion donde llegar local mapa',true,4),
('00000000-0000-4000-8000-000000000005','SERVICIOS','¿Qué servicios ofrecen?','Dato ficticio de ejemplo: ofrecemos consulta informativa general. El catálogo clínico aún no está configurado; consulta directamente al equipo para servicios específicos.','servicios ofrecen especialidades consulta atencion',true,5),
('00000000-0000-4000-8000-000000000006','PRECIOS','¿Cuánto cuesta una consulta?','El precio de la consulta aún no está configurado. Solicita la tarifa actual al canal de contacto del consultorio.','precio precios costo cuesta tarifa consulta pago',true,6),
('00000000-0000-4000-8000-000000000007','PRECIOS','¿Cuánto cuesta un servicio específico?','No dispongo de una tarifa para ese servicio. Consulta el precio directamente con el equipo del consultorio.','precio precios costo cuesta servicio especifico tratamiento',true,7),
('00000000-0000-4000-8000-000000000008','CONTACTO','¿Cómo me comunico con el consultorio?','El teléfono de contacto aún no está configurado para esta demostración. Consulta al equipo responsable por el canal que te proporcionó este bot.','contacto telefono llamar escribir comunicar whatsapp numero',true,8),
('00000000-0000-4000-8000-000000000009','CITAS','¿Cómo solicito una cita?','Puedes solicitar una cita por el canal de contacto que configure el equipo. Este bot no registra ni confirma reservas.','cita citas turno reservar reserva agendar agenda solicitar',true,9),
('00000000-0000-4000-8000-000000000010','CITAS','¿Puedes reservarme mañana a las 10?','No puedo reservar ni confirmar una cita. Para consultar disponibilidad y solicitarla, usa el canal de contacto del consultorio.','reservarme reservar cita manana diez 10 disponibilidad',true,10),
('00000000-0000-4000-8000-000000000011','SERVICIOS','¿Atienden urgencias?','No dispongo de información sobre atención de urgencias en este consultorio ficticio. Ante una urgencia real, acude a un servicio de emergencia local.','urgencia urgencias emergencia emergencias',true,11),
('00000000-0000-4000-8000-000000000012','UBICACION','¿En qué ciudad están?','Dato ficticio de ejemplo: el consultorio está en Ica, Perú.','ciudad distrito ica peru ubicacion',true,12);
